/* FORGE photo atlas · Runde 3 (Brust und Unterkörper).
 * Eight real-looking generated studio exercise triptychs. No user state changes.
 * The original FORGE pictures and earlier photo rounds remain untouched.
 * Illustrated pose examples must be checked against written exercise instructions.
 */
(function(){
'use strict';
const photoAssets={"Brustpresse":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Butterfly / Pec Deck":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Kabel-Flys":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Beinstrecker":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Abduktorenmaschine":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Adduktorenmaschine":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Einbeiniges rumänisches Kreuzheben":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Back Extensions":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
const names=Object.keys(photoAssets);
const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const previousAtlas=window.forgeExerciseIllustrations;
const previousCatalog=window.forgePublicExercisePictures;
function picture(name){
 const seq=photoAssets[name];if(!seq)return '';
 const captions=['1 · Startposition','2 · Endposition','3 · Beanspruchte Muskeln'];
 return '<div class="forge166-photo-grid forge167-photo-grid" data-forge167-photo="'+safe(name)+'">'+
   seq.map((src,i)=>'<figure class="forge166-photo"><img loading="lazy" decoding="async" src="'+src+'" alt="'+safe(name)+' – '+captions[i]+'"><figcaption>'+captions[i]+'</figcaption></figure>').join('')+
  '</div><p class="forge166-photo-footnote">Orientierung: Die abgebildeten Positionen anhand der Übungserklärung prüfen.</p>';
}
window.forgeExerciseIllustrations=function(name){return Object.hasOwn(photoAssets,name)?picture(name):(typeof previousAtlas==='function'?previousAtlas(name):'');};
window.forgePublicExercisePictures=function(name){return Object.hasOwn(photoAssets,name)?picture(name):(typeof previousCatalog==='function'?previousCatalog(name):'');};
window.forge167BatchInfo={names,picture};
})();